namespace sv_a0cb3ac2155d44e8aacd4558fdba0082.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_a0cb3ac2155d44e8aacd4558fdba0082.Services

<div class="message-container" @onmouseenter="ShowActions" @onmouseleave="HideActions">
    <div class="message-header">
        <span class="author">@Message.Author</span>
        <span class="timestamp">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => OnReact.InvokeAsync((Message.Id, reaction.Emoji))">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ThreadInfo is not null)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            💬 @ThreadInfo.ReplyCount @(ThreadInfo.ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (_showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)" title="Reply in thread">
                💬 Reply
            </button>
            <button class="action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">
                😀 React
            </button>
        </div>

        @if (_showEmojiPicker)
        {
            <div class="emoji-picker">
                @foreach (var emoji in _commonEmojis)
                {
                    <button class="emoji-btn" @onclick="() => SelectEmoji(emoji)">@emoji</button>
                }
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public ThreadSummary? ThreadInfo { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool _showActions;
    private bool _showEmojiPicker;

    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "👀"];

    private void ShowActions() => _showActions = true;

    private void HideActions()
    {
        _showActions = false;
        _showEmojiPicker = false;
    }

    private void ToggleEmojiPicker() => _showEmojiPicker = !_showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        _showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var elapsed = DateTime.UtcNow - sentAt;

        if (elapsed.TotalSeconds < 60) return "just now";
        if (elapsed.TotalMinutes < 60) return $"{(int)elapsed.TotalMinutes} min ago";
        if (elapsed.TotalHours < 24) return $"{(int)elapsed.TotalHours}h ago";
        if (elapsed.TotalDays < 7) return $"{(int)elapsed.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.message-container {
    position: relative;
    padding: 8px 12px;
    border-radius: 6px;
    transition: background-color 0.15s;
}

.message-container:hover {
    background-color: rgba(0, 0, 0, 0.04);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1d1c1d;
}

.timestamp {
    font-size: 0.75rem;
    color: #616061;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.5;
    color: #1d1c1d;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background: #e0e0f0;
    border-color: #aab;
}

.thread-link {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-top: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    color: #1264a3;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 600;
}

.thread-link:hover {
    background: #e8f0fe;
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 8px;
    display: flex;
    gap: 2px;
    padding: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);
    z-index: 10;
}

.action-btn {
    padding: 4px 8px;
    font-size: 0.78rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    color: #616061;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
    color: #1d1c1d;
}

.emoji-picker {
    position: absolute;
    top: -12px;
    right: 160px;
    display: flex;
    gap: 2px;
    padding: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    z-index: 11;
}

.emoji-btn {
    padding: 4px 6px;
    font-size: 1.2rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    line-height: 1;
}

.emoji-btn:hover {
    background: #f0f0f0;
    transform: scale(1.2);
}

@using sv_a0cb3ac2155d44e8aacd4558fdba0082.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h4>Channels</h4>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-top-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string desc)
        => desc.Length > 50 ? string.Concat(desc.AsSpan(0, 47), "...") : desc;
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #3f0e40;
    color: #fff;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.15);
}

.sidebar-header h4 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-item {
    display: block;
    width: 100%;
    padding: 8px 16px;
    text-align: left;
    background: none;
    border: none;
    color: rgba(255, 255, 255, 0.7);
    cursor: pointer;
    border-radius: 0 6px 6px 0;
    margin-right: 8px;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.channel-item.active {
    background: #1164a3;
    color: #fff;
}

.channel-top-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-size: 0.9rem;
    font-weight: 600;
}

.channel-desc {
    font-size: 0.75rem;
    margin-top: 2px;
    opacity: 0.65;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.unread-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    font-size: 0.7rem;
    font-weight: 700;
    background: #e01e5a;
    color: #fff;
    border-radius: 10px;
}

