toolArgs.file_text:
.message-container {
    position: relative;
    padding: 8px 12px;
    border-radius: 6px;
    transition: background-color 0.15s;
}

.message-container:hover {
    background-color: rgba(0, 0, 0, 0.04);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1d1c1d;
}

.timestamp {
    font-size: 0.75rem;
    color: #616061;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.5;
    color: #1d1c1d;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background: #e0e0f0;
    border-color: #aab;
}

.thread-link {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-top: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    color: #1264a3;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 600;
}

.thread-link:hover {
    background: #e8f0fe;
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 8px;
    display: flex;
    gap: 2px;
    padding: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);
    z-index: 10;
}

.action-btn {
    padding: 4px 8px;
    font-size: 0.78rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    color: #616061;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
    color: #1d1c1d;
}

.emoji-picker {
    position: absolute;
    top: -12px;
    right: 160px;
    display: flex;
    gap: 2px;
    padding: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    z-index: 11;
}

.emoji-btn {
    padding: 4px 6px;
    font-size: 1.2rem;
    background: none;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    line-height: 1;
}

.emoji-btn:hover {
    background: #f0f0f0;
    transform: scale(1.2);
}

