toolArgs.file_text:
@using sv_a0cb3ac2155d44e8aacd4558fdba0082.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h4>Channels</h4>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <button class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                    @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-top-row">
                    <span class="channel-name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                }
            </button>
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string desc)
        => desc.Length > 50 ? string.Concat(desc.AsSpan(0, 47), "...") : desc;
}

.channel-sidebar {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #3f0e40;
    color: #fff;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.15);
}

.sidebar-header h4 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-item {
    display: block;
    width: 100%;
    padding: 8px 16px;
    text-align: left;
    background: none;
    border: none;
    color: rgba(255, 255, 255, 0.7);
    cursor: pointer;
    border-radius: 0 6px 6px 0;
    margin-right: 8px;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.channel-item.active {
    background: #1164a3;
    color: #fff;
}

.channel-top-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-size: 0.9rem;
    font-weight: 600;
}

.channel-desc {
    font-size: 0.75rem;
    margin-top: 2px;
    opacity: 0.65;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.unread-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    font-size: 0.7rem;
    font-weight: 700;
    background: #e01e5a;
    color: #fff;
    border-radius: 10px;
}

