        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        <div @ref="_sentinelRef" class="scroll-sentinel"></div>

        @foreach (var message in Messages)
        {
            <ChatMessage Message="message"
                         ThreadInfo="GetThreadInfo(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-textarea"
                  @bind="NewMessageText"
                  @bind:event="oninput"
                  @onkeydown="HandleKeyDown"
                  placeholder="@($"Message #{ChannelName}")"
                  rows="1"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(NewMessageText)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private ElementReference _sentinelRef;
    private IJSObjectReference? _module;
    private IJSObjectReference? _observer;
    private DotNetObjectReference<MessageArea>? _dotNetRef;
    private string NewMessageText = "";
    private bool _initialized;
    private bool _shouldScrollToBottom = true;

    private ThreadSummary? GetThreadInfo(int messageId)
        => ThreadSummaries.GetValueOrDefault(messageId);

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import",
                "./Components/Pages/Chat/MessageArea.razor.js");
            _dotNetRef = DotNetObjectReference.Create(this);
            _observer = await _module.InvokeAsync<IJSObjectReference>(
                "initScrollObserver", _sentinelRef, _dotNetRef);
            _initialized = true;
        }

        if (_shouldScrollToBottom && _module is not null)
        {
            await _module.InvokeVoidAsync("scrollToBottom", _messageListRef);
            _shouldScrollToBottom = false;
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (!IsLoadingMore && Messages.Count > 0)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    /// <summary>Call from parent after loading a new channel to auto-scroll down.</summary>
    public void RequestScrollToBottom() => _shouldScrollToBottom = true;

    /// <summary>Call from parent after prepending older messages to preserve scroll position.</summary>
    public async Task PreserveScroll(double previousScrollHeight)
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("preserveScrollPosition", _messageListRef, previousScrollHeight);
        }
    }

    public async Task<double> GetScrollHeight()
    {
        if (_module is not null)
            return await _module.InvokeAsync<double>("getScrollHeight", _messageListRef);
        return 0;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        var text = NewMessageText?.Trim();
        if (string.IsNullOrEmpty(text)) return;

        NewMessageText = "";
        _shouldScrollToBottom = true;
        await OnSendMessage.InvokeAsync(text);
    }

    public async ValueTask DisposeAsync()
    {
        if (_observer is not null)
        {
            if (_module is not null)
                await _module.InvokeVoidAsync("disposeObserver", _observer);
            await _observer.DisposeAsync();
        }
        _dotNetRef?.Dispose();
        if (_module is not null) await _module.DisposeAsync();
    }
}
