toolArgs.file_text:
.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    border-left: 1px solid #ddd;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-header h4 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #1d1c1d;
}

.close-btn {
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    color: #616061;
    cursor: pointer;
}

.close-btn:hover {
    background: #f0f0f0;
    color: #1d1c1d;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    background: #f8f8f8;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1d1c1d;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.88rem;
    line-height: 1.45;
    color: #333;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-replies-divider {
    padding: 8px 16px;
    flex-shrink: 0;
}

.thread-replies-divider span {
    font-size: 0.78rem;
    font-weight: 600;
    color: #616061;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0 16px 8px;
}

.thread-reply {
    padding: 8px 0;
}

.thread-reply + .thread-reply {
    border-top: 1px solid #f0f0f0;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #1d1c1d;
}

.reply-time {
    font-size: 0.72rem;
    color: #888;
}

.reply-content {
    font-size: 0.85rem;
    line-height: 1.45;
    color: #1d1c1d;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-textarea {
    flex: 1;
    padding: 8px 10px;
    border: 1px solid #ccc;
    border-radius: 8px;
    font-size: 0.85rem;
    font-family: inherit;
    resize: none;
    min-height: 36px;
    max-height: 100px;
    outline: none;
}

.thread-textarea:focus {
    border-color: #1264a3;
    box-shadow: 0 0 0 1px #1264a3;
}

.reply-btn {
    padding: 8px 16px;
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reply-btn:hover:not(:disabled) {
    background: #005e44;
}

.reply-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

