arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_a0cb3ac2155d44e8aacd4558fdba0082.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel @(_isThreadOpen ? "" : "main-panel-expanded")">
        @if (_selectedChannel is not null)
        {
            <MessageArea @ref="_messageArea"
                         ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         IsLoadingMore="_isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_isThreadOpen)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadReplies = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    private Channel? _selectedChannel;
    private int _selectedChannelId;
    private Message? _threadRootMessage;
    private int? _activeThreadRootId;
    private bool _isThreadOpen;
    private bool _isLoadingMore;
    private int _messageSkip;
    private bool _hasMoreMessages = true;

    private MessageArea? _messageArea;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (_selectedChannelId == channelId && _selectedChannel is not null)
            return;

        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messageSkip = 0;
        _hasMoreMessages = true;
        _threadSummaries.Clear();

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messageSkip = _messages.Count;
        _hasMoreMessages = _messages.Count >= PageSize;

        await ChatService.MarkChannelReadAsync(channelId);
        RefreshChannelUnreadCount(channelId);

        CloseThreadSync();
        _messageArea?.RequestScrollToBottom();
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || !_hasMoreMessages || _selectedChannel is null)
            return;

        _isLoadingMore = true;
        StateHasChanged();

        double previousHeight = 0;
        if (_messageArea is not null)
            previousHeight = await _messageArea.GetScrollHeight();

        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
        }
        _hasMoreMessages = older.Count >= PageSize;
        _isLoadingMore = false;
        StateHasChanged();

