+    private List<Channel> _channels = [];
+    private List<Message> _messages = [];
+    private List<Message> _threadReplies = [];
+    private Dictionary<int, ThreadSummary> _threadSummaries = new();
+
+    private Channel? _selectedChannel;
+    private int _selectedChannelId;
+    private Message? _threadRootMessage;
+    private int? _activeThreadRootId;
+    private bool _isThreadOpen;
+    private bool _isLoadingMore;
+    private int _messageSkip;
+    private bool _hasMoreMessages = true;
+
+    private MessageArea? _messageArea;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _channels = await ChatService.GetChannelsAsync();
+
+        if (_channels.Count > 0)
+        {
+            await SelectChannel(_channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        if (_selectedChannelId == channelId && _selectedChannel is not null)
+            return;
+
+        _selectedChannelId = channelId;
+        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
+        _messageSkip = 0;
+        _hasMoreMessages = true;
+        _threadSummaries.Clear();
+
+        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        _messageSkip = _messages.Count;
+        _hasMoreMessages = _messages.Count >= PageSize;
+
+        await ChatService.MarkChannelReadAsync(channelId);
+        RefreshChannelUnreadCount(channelId);
+
+        CloseThreadSync();
+        _messageArea?.RequestScrollToBottom();
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (_isLoadingMore || !_hasMoreMessages || _selectedChannel is null)
+            return;
+
+        _isLoadingMore = true;
+        StateHasChanged();
+
+        double previousHeight = 0;
+        if (_messageArea is not null)
+            previousHeight = await _messageArea.GetScrollHeight();
+
+        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messageSkip, PageSize);
+        if (older.Count > 0)
+        {
+            _messages.InsertRange(0, older);
+            _messageSkip += older.Count;
+        }
+        _hasMoreMessages = older.Count >= PageSize;
+        _isLoadingMore = false;
+        StateHasChanged();
+
+        // Preserve scroll position after prepending messages
+        await Task.Yield();
+        if (_messageArea is not null)
+            await _messageArea.PreserveScroll(previousHeight);
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (_selectedChannel is null) return;
+
+        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
+        _messages.Add(message);
+        _messageSkip++;
+        _messageArea?.RequestScrollToBottom();
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        _activeThreadRootId = messageId;
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
+        _threadReplies = await ChatService.GetThreadAsync(messageId);
+        _isThreadOpen = true;
+
+        // Update thread summary
+        if (_threadReplies.Count > 0)
+        {
+            _threadSummaries[messageId] = new ThreadSummary(
+                messageId,
+                _threadReplies.Count,
+                _threadReplies[^1].SentAt);
+        }
+    }
+
+    private void CloseThread()
+    {
+        CloseThreadSync();
+    }
+
+    private void CloseThreadSync()
+    {
+        _isThreadOpen = false;
+        _activeThreadRootId = null;
+        _threadRootMessage = null;
+        _threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (_activeThreadRootId is null || _selectedChannel is null) return;
+
+        var reply = await ChatService.SendMessageAsync(
+            _selectedChannel.Id, content, _activeThreadRootId);
+        _threadReplies.Add(reply);
+
+        // Update thread summary
+        _threadSummaries[_activeThreadRootId.Value] = new ThreadSummary(
+            _activeThreadRootId.Value,
+            _threadReplies.Count,
+            reply.SentAt);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistically update the local message's reactions
+        var message = _messages.FirstOrDefault(m => m.Id == args.MessageId);
+        if (message is not null)
+        {
+            var existing = message.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (existing is not null)
+            {
+                if (!existing.Users.Contains("You"))
+                    existing.Users.Add("You");
+            }
+            else
+            {
+                message.Reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+        }
+    }
+
+    private void RefreshChannelUnreadCount(int channelId)
+    {
+        var idx = _channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+        {
+            var ch = _channels[idx];
+            _channels[idx] = ch with { UnreadCount = 0 };
+        }
+    }
+}
